type SessionUser = { id: string; role: "member" | "admin" } | null;
type AuthDecision =
  | { status: 200; userId: string }
  | { status: 401 }
  | { status: 403 };

function authorizeWrite(user: SessionUser): AuthDecision {
  // TODO: return 401 for no session, 403 for a non-admin, and 200 for an admin
  return { status: 200, userId: user?.id ?? "anonymous" };
}

